export function getMapStateByTraditionSlug(slug) {
  if (!slug) return null;
  const normalized = String(slug).trim().toLowerCase();
  // Prefer Jammu & Kashmir over Ladakh when matching pashmina
  if (normalized === "pashmina") {
    return (
      INDIA_MAP_STATES.find((s) => s.name === "Jammu & Kashmir") ||
      INDIA_MAP_STATES.find((s) => s.traditionSlug === normalized) ||
      null
    );
  }
  return INDIA_MAP_STATES.find((s) => s.traditionSlug === normalized) || null;
}
